#include <stdio.h>
#include <string.h>

const int MAXN=60;
const int MOD=1000000007;
long long n;
int k;

inline int add(int x){return x>=MOD?x-MOD:x;}
inline int sub(int x){return x<0?x+MOD:x;}
inline int mul(int x,int y){return (long long) x * y % MOD;}

struct Matrix {
    int a[MAXN][MAXN];
    int n;
    void init() { memset(a, 0, sizeof(a)); }
    void set() {
        init();
        for (int i=1; i<=n; i++) a[i][i]=1;
    }
    Matrix operator *(const Matrix &rhs) const {
        Matrix ans; ans.n=n;
        long long tmp[MAXN][MAXN]; memset(tmp, 0, sizeof(tmp));
        const long long MODLL=(LL)MOD*MOD;
        for (int i=1; i<=n; i++) {
            for (int j=1; j<=n; j++) {
                for (int k=1; k<=n; k++) {
                    tmp[i][j]+= (LL)a[i][k]*rhs.a[k][j];
                    if (tmp[i][j]>=MODLL) tmp[i][j]-=MODLL;
                }
            }
        }
        for (int i=1; i<=n; i++){
            for (int j=1; j<=n; j++){
                ans.a[i][j]=tmp[i][j]%MOD;
            }
        }
        return ans;
    }
};

std::vector<std::vector<Matrix>> F, sumP, sumS;
std::vector<int> Num;
int cnt;

void cal() {
    Num.clear(); F.clear(); sumP.clear(); sumS.clear();
    for (long long x=n; x; x/=k) Num.push_back(x%k);
    cnt= (int)Num.size();

    F.resize(cnt, std::vector<Matrix>(k));
    sumP.resize(cnt, std::vector<Matrix>(k));
    sumS.resize(cnt, std::vector<Matrix>(k));

    for (int i=0; i<cnt; i++) {
        for (int j=0; j<k; j++) {
            F[i][j].n=k+1; F[i][j].init(); F[i][j].set();
            for (int t=1; t<=k+1; t++){
                F[i][j].a[t][t]=1;
            }
            for (int t=1; t<=k+1; t++){
                F[i][j].a[i+1][t]=1;
            }
        }
    }

    for (int j=0;j<k;j++) {
        sumP[0][j]=F[0][j];
    }

    for (int i=1; i<cnt; i++){
        for (int j=0;j<k;j++){
            int idx= (j==0)?0:j;
            F[i][j]= (j==0)?sumS[i-1][j]:sumP[i-1][j-1]*sumS[i-1][j];
        }
        for (int j=0;j<k;j++){
            if(j==0) sumP[i][j]=F[i][j];
            else sumP[i][j]=F[i][j]*sumP[i][j-1];
        }
        for (int j=k-2;j>=0;j--){
            sumS[i][j]=sumS[i][j+1]*F[i][j];
        }
    }

    Matrix ans; ans.n=k+1; ans.set();
    int total=0;
    for (int i=cnt-1; i>=0; i--) {
        for (int j=0; j<Num[i]; j++) {
            int idx=(total+j)%k;
            ans=F[i][idx]*ans;
        }
        total+=Num[i]; total%=k;
    }

    int res=0;
    for (int i=1; i<=k+1; i++) {
        res=add(res+ans.a[i][k+1]);
    }
    printf("%d\n", res);
}

int main() {
    scanf("%lld %d", &n, &k);
    cal();
}
